python3 -c "
COLORMAP = [(0,0,0), (0,0,128), (0,0,255), (128,160,255), (255,255,255)]
def rgb565(b,g,r):
    return (((r)<<8)&0xf800)|(((g)<<3)&0x07e0)|(((b)>>3)&0x001f)
def pick_color(mag):
    idx, prop = (mag>>4)&3, mag&15
    nprop = 16-prop
    c0,c1 = COLORMAP[idx],COLORMAP[idx+1]
    r=(c0[0]*nprop+c1[0]*prop)>>4; g=(c0[1]*nprop+c1[1]*prop)>>4; b=(c0[2]*nprop+c1[2]*prop)>>4
    return rgb565(r,g,b), (r,g,b)
def unpack(p):
    return ((p>>8)&0xf8,(p>>3)&0xfc,(p<<3)&0xf8)
for m,stop in [(16,1),(32,2),(48,3)]:
    pix,(r,g,b)=pick_color(m)
    print('mag=%d rgb_in=(%d,%d,%d) pixel=0x%04x unpack_std=%s colormap[%d]_rgb=(%d,%d,%d)'%(m,r,g,b,pix,unpack(pix),stop,*COLORMAP[stop]))
print('mag=20:', pick_color(20))
print('mag=0 :', pick_color(0))
"
